#!/usr/bin/env bash
# keizu — clj/bb test suite (ADR-2606160842 py->clj port wave; Python pruned).
set -euo pipefail
cd "$(dirname "$0")/../.."
exec bb -e '(require (quote clojure.test) (quote keizu.methods.test-analyze) (quote keizu.methods.test-autorun) (quote keizu.methods.test-bridge) (quote keizu.methods.test-charter-invariants) (quote keizu.methods.test-consistency) (quote keizu.methods.test-edn) (quote keizu.methods.test-export) (quote keizu.methods.test-ingest) (quote keizu.methods.test-kotoba) (quote keizu.methods.test-lexicons) (quote keizu.methods.test-registry) (quote keizu.methods.test-social) (quote keizu.methods.test-sources) (quote keizu.methods.test-weave) (quote keizu.cells.test-state-machines) (quote keizu.cells.test-membrane-flow))(let [r (apply clojure.test/run-tests (quote [keizu.methods.test-analyze keizu.methods.test-autorun keizu.methods.test-bridge keizu.methods.test-charter-invariants keizu.methods.test-consistency keizu.methods.test-edn keizu.methods.test-export keizu.methods.test-ingest keizu.methods.test-kotoba keizu.methods.test-lexicons keizu.methods.test-registry keizu.methods.test-social keizu.methods.test-sources keizu.methods.test-weave keizu.cells.test-state-machines keizu.cells.test-membrane-flow]))](System/exit (if (zero? (+ (:fail r) (:error r))) 0 1)))'
